// Electricity Circuit Visualization - Electron Flow Demonstration
const curve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(-4, 0, 0),
    new THREE.Vector3(-4, 3, 0),
    new THREE.Vector3(4, 3, 0),
    new THREE.Vector3(4, 0, 0),
    new THREE.Vector3(1, 0, 0),
    new THREE.Vector3(1, -3, 0),
    new THREE.Vector3(-1, -3, 0),
    new THREE.Vector3(-1, 0, 0),
    new THREE.Vector3(-4, 0, 0)
], true);

const tubeGeometry = new THREE.TubeGeometry(curve, 100, 0.12, 8, true);
const wireMaterial = new THREE.MeshStandardMaterial({ 
    color: 0x666666, 
    metalness: 0.9, 
    roughness: 0.1 
});
const wire = new THREE.Mesh(tubeGeometry, wireMaterial);
scene.add(wire);

const electronCount = 40;
const electronGeometry = new THREE.SphereGeometry(0.12, 16, 16);
const electronMaterial = new THREE.MeshBasicMaterial({ color: 0x00ffff });
const electrons = [];

for (let i = 0; i < electronCount; i++) {
    const electron = new THREE.Mesh(electronGeometry, electronMaterial);
    scene.add(electron);
    electrons.push({
        mesh: electron,
        progress: i / electronCount,
        speed: 0.003
    });
}

const batteryGroup = new THREE.Group();
batteryGroup.position.set(-4, 1.5, 0);

const batteryBody = new THREE.Mesh(
    new THREE.CylinderGeometry(0.9, 0.9, 2.2, 32),
    new THREE.MeshStandardMaterial({ color: 0x222222, metalness: 0.6, roughness: 0.4 })
);
batteryBody.rotation.z = Math.PI / 2;
batteryGroup.add(batteryBody);

const posTerminal = new THREE.Mesh(
    new THREE.CylinderGeometry(0.35, 0.35, 0.25, 16),
    new THREE.MeshStandardMaterial({ color: 0xff0000, emissive: 0x330000 })
);
posTerminal.rotation.z = Math.PI / 2;
posTerminal.position.x = 1.2;
batteryGroup.add(posTerminal);

const negTerminal = new THREE.Mesh(
    new THREE.CylinderGeometry(0.35, 0.35, 0.25, 16),
    new THREE.MeshStandardMaterial({ color: 0x111111 })
);
negTerminal.rotation.z = Math.PI / 2;
negTerminal.position.x = -1.2;
batteryGroup.add(negTerminal);

const posBand = new THREE.Mesh(
    new THREE.CylinderGeometry(0.92, 0.92, 0.4, 32),
    new THREE.MeshBasicMaterial({ color: 0xff0000 })
);
posBand.rotation.z = Math.PI / 2;
posBand.position.x = 0.8;
batteryGroup.add(posBand);

scene.add(batteryGroup);

const bulbGroup = new THREE.Group();
bulbGroup.position.set(0, -3, 0);

const bulbBase = new THREE.Mesh(
    new THREE.CylinderGeometry(0.45, 0.45, 0.9, 16),
    new THREE.MeshStandardMaterial({ color: 0x888888, metalness: 0.9 })
);
bulbGroup.add(bulbBase);

const bulbGlass = new THREE.Mesh(
    new THREE.SphereGeometry(0.9, 32, 32),
    new THREE.MeshPhysicalMaterial({ 
        color: 0xffffee, 
        transmission: 0.8, 
        opacity: 0.4, 
        transparent: true,
        roughness: 0,
        metalness: 0
    })
);
bulbGlass.position.y = 0.9;
bulbGroup.add(bulbGlass);

const filament = new THREE.Mesh(
    new THREE.TorusGeometry(0.35, 0.03, 8, 20, Math.PI),
    new THREE.MeshBasicMaterial({ color: 0xff6600 })
);
filament.position.y = 0.9;
filament.rotation.x = Math.PI / 2;
bulbGroup.add(filament);

const bulbLight = new THREE.PointLight(0xffaa00, 0, 15);
bulbLight.position.y = 0.9;
bulbGroup.add(bulbLight);

scene.add(bulbGroup);

const ambientLight = new THREE.AmbientLight(0x404040);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 1);
dirLight.position.set(5, 10, 7);
scene.add(dirLight);

const arrowGeometry = new THREE.ConeGeometry(0.15, 0.4, 8);
const arrowMaterial = new THREE.MeshBasicMaterial({ color: 0x00ff00, transparent: true, opacity: 0.5 });
const arrows = [];

for (let i = 0; i < 10; i++) {
    const arrow = new THREE.Mesh(arrowGeometry, arrowMaterial);
    const t = i / 10;
    const point = curve.getPointAt(t);
    const tangent = curve.getTangentAt(t);
    arrow.position.copy(point);
    arrow.position.y += 0.4;
    arrow.lookAt(point.clone().add(tangent));
    arrow.rotateX(Math.PI / 2);
    scene.add(arrow);
    arrows.push({ mesh: arrow, progress: t });
}

let time = 0;

function animate() {
    requestAnimationFrame(animate);
    time += 0.016;

    electrons.forEach(e => {
        e.progress += e.speed;
        if (e.progress > 1) e.progress -= 1;

        const point = curve.getPointAt(e.progress);
        e.mesh.position.copy(point);
        e.mesh.position.y += Math.sin(time * 15 + e.progress * 20) * 0.03;
    });

    arrows.forEach((a, i) => {
        a.progress += 0.0008;
        if (a.progress > 1) a.progress -= 1;

        const point = curve.getPointAt(a.progress);
        const tangent = curve.getTangentAt(a.progress);
        a.mesh.position.copy(point);
        a.mesh.position.y += 0.4 + Math.sin(time * 3 + i) * 0.08;
        a.mesh.lookAt(point.clone().add(tangent));
        a.mesh.rotateX(Math.PI / 2);
    });

    const pulse = Math.sin(time * 8) * 0.5 + 1.5;
    bulbLight.intensity = pulse * 2;
    filament.material.color.setHSL(0.08, 1, 0.4 + Math.sin(time * 8) * 0.3);

    const wirePulse = Math.sin(time * 5) * 0.05;
    wire.material.emissive.setRGB(0, wirePulse, wirePulse * 2);

    renderer.render(scene, camera);
}

animate();

camera.position.set(0, 0, 14);
camera.lookAt(0, 0, 0);

